package main

import (
	"fmt"
	"log"
	"net/http"
	"os/exec"
	"strings"
	"sync"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

type DiagnosticService struct {
	mu      sync.Mutex
	clients map[*websocket.Conn]bool
}

func NewDiagnosticService() *DiagnosticService {
	return &DiagnosticService{
		clients: make(map[*websocket.Conn]bool),
	}
}

// handleDiagnostic processes real-time diagnostic commands from operators
func (ds *DiagnosticService) handleDiagnostic(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	ds.mu.Lock()
	ds.clients[conn] = true
	ds.mu.Unlock()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			ds.mu.Lock()
			delete(ds.clients, conn)
			ds.mu.Unlock()
			break
		}

		cmd := string(message)
		result := ds.executeProbe(cmd)
		conn.WriteMessage(websocket.TextMessage, []byte(result))
	}
}

// executeProbe runs network diagnostic probes for the operator console
// Supported: ping, traceroute, dig, nslookup
func (ds *DiagnosticService) executeProbe(input string) string {
	parts := strings.Fields(input)
	if len(parts) < 2 {
		return "error: usage: <command> <target>"
	}

	command := parts[0]
	allowedCommands := map[string]bool{
		"ping":       true,
		"traceroute": true,
		"dig":        true,
		"nslookup":   true,
	}

	if !allowedCommands[command] {
		return fmt.Sprintf("error: command '%s' not permitted", command)
	}

	target := strings.Join(parts[1:], " ")

	// Construct the shell command for execution
	// Using sh -c to handle complex arguments like dig options
	fullCmd := fmt.Sprintf("%s %s", command, target)
	out, err := exec.Command("sh", "-c", fullCmd).CombinedOutput()
	if err != nil {
		return fmt.Sprintf("probe failed: %s\n%s", err.Error(), string(out))
	}

	return string(out)
}

// healthCheck provides liveness probe endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	ds := NewDiagnosticService()

	http.HandleFunc("/ws/diagnostic", ds.handleDiagnostic)
	http.HandleFunc("/healthz", healthCheck)

	log.Println("diagnostic-service starting on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("server error: %v", err)
	}
}
